pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 minSum1, uint256 minSum2) internal {
        vm.assume(minSum1 != minSum2);
        try c.SetMinSum(minSum1) {} catch { return; }
        try c.Initialized() {} catch { return; }
        bool revertedMinSum;
        try c.SetMinSum(minSum2) { revertedMinSum = false; } catch { revertedMinSum = true; }
        bool revertedLogFile;
        try c.SetLogFile(address(this)) { revertedLogFile = false; } catch { revertedLogFile = true; }
        assertTrue(revertedMinSum && revertedLogFile && c.MinSum() == minSum1);
    }

    function testFuzz_run(uint256 minSum1, uint256 minSum2) public {
        _run(minSum1, minSum2);
    }

    receive() external payable {}
}
